import { _decorator, Component } from 'cc';
import { MonsterSpawner } from './MonsterSpawner';
import { CoinEvents, CoinEventName } from './CoinEvents';
const { ccclass, property } = _decorator;

/** 소켓에 코인이 한 개라도 흡수되는 순간(SocketAbsorbed) 러쉬를 한 번 시작시키는 트리거 */
@ccclass('RushStartTrigger')
export class RushStartTrigger extends Component {
    @property(MonsterSpawner) spawner: MonsterSpawner | null = null;

    @property({ displayName: '시작할 러쉬 이름' })
    rushName: string = 'Rush_1';

    private _triggered = false;
    private _onSocketAbsorbed = () => this._trigger();

    onLoad() {
        CoinEvents.on(CoinEventName.SocketAbsorbed, this._onSocketAbsorbed);
    }

    onDestroy() {
        CoinEvents.off(CoinEventName.SocketAbsorbed, this._onSocketAbsorbed);
    }

    private _trigger() {
        if (this._triggered || !this.spawner) return;
        this._triggered = true;
        CoinEvents.off(CoinEventName.SocketAbsorbed, this._onSocketAbsorbed);
        this.spawner.startRushByName(this.rushName);
    }
}
